mapper.select:
SELECT id, user_id, stock_code, hold_count, buy_total_cost
FROM user_stock_hold
WHERE user_id = #{userId}
  AND stock_code = #{stockCode}
LIMIT 1

mapper.update:
UPDATE user_stock_hold
SET hold_count = #{holdCount}
WHERE id = #{id}

UPDATE user_stock_hold
SET hold_count = #{holdCount},
    buy_total_cost = #{buyTotalCost}
WHERE id = #{id}

mapper.delete:
DELETE FROM user_stock_hold
WHERE user_id = #{userId}
  AND stock_code = #{stockCode}
